import itertools

def max_probability(n, p):
    max_prob = 0.0
    for r in range(1, n + 1):
        for combo in itertools.combinations(p, r):
            prob = 1.0
            for prob_i in combo:
                prob *= prob_i
            for prob_j in p:
                if prob_j not in combo:
                    prob *= (1 - prob_j)
            max_prob = max(max_prob, prob)
    return max_prob

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    p = list(map(float, data[1:]))
    result = max_probability(n, p)
    print(f"{result:.12f}")
